import{_ as e,o as t,c as a,a2 as s}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse(`{"title":"Security and Privacy","description":"Hearth's trust boundaries, threat model, Capability model, risk classification, credentials, Sandbox, prompt injection, privacy, and incident response.","frontmatter":{"title":"Security and Privacy","description":"Hearth's trust boundaries, threat model, Capability model, risk classification, credentials, Sandbox, prompt injection, privacy, and incident response.","outline":[2,3]},"headers":[],"relativePath":"en/architecture/security-privacy.md","filePath":"en/architecture/security-privacy.md","lastUpdated":1793706118000}`),n={name:"en/architecture/security-privacy.md"};function r(l,i,o,d,c,p){return t(),a("div",null,[...i[0]||(i[0]=[s(`<p class="eyebrow">SECURITY &amp; PRIVACY</p><h1 id="security-and-privacy" tabindex="-1">Security and Privacy <a class="header-anchor" href="#security-and-privacy" aria-label="Permalink to &quot;Security and Privacy&quot;">​</a></h1><p class="lead">Security is not a pre-release check; it is a product capability. Trust boundaries, Capability, risk classification, credentials, and incident response must all be reflected in the architecture.</p><h2 id="security-is-a-product-capability" tabindex="-1">Security Is a Product Capability <a class="header-anchor" href="#security-is-a-product-capability" aria-label="Permalink to &quot;Security Is a Product Capability&quot;">​</a></h2><p>Hearth security is not &quot;adding an approval dialog&quot;; it is a system capability that spans provenance, context, permissions, execution, side effects, and recovery. Models are not trusted execution environments, web pages are not trusted instructions, documents are not trusted code, and data returned by Connectors is not automatically trusted.</p><h3 id="trust-boundaries" tabindex="-1">Trust Boundaries <a class="header-anchor" href="#trust-boundaries" aria-label="Permalink to &quot;Trust Boundaries&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Untrusted external content</span></span>
<span class="line"><span>  → Gateway normalization</span></span>
<span class="line"><span>  → Policy / data labeling</span></span>
<span class="line"><span>  → Minimal context</span></span>
<span class="line"><span>  → Executor</span></span>
<span class="line"><span>  → Sandbox</span></span>
<span class="line"><span>  → Effect Dispatcher</span></span>
<span class="line"><span>  → External systems</span></span></code></pre></div><p>Each layer assumes the next layer may be compromised. External content can influence task content, but cannot expand permissions, modify Policy, or directly trigger high-risk side effects.</p><h3 id="threat-model" tabindex="-1">Threat model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat model&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Threat</th><th>Scenario</th><th>Defense</th></tr></thead><tbody><tr><td>Prompt injection</td><td>Web pages/emails request file leaks or instruct ignoring rules</td><td>Data-instruction separation, tool allowlist, untrusted markers</td></tr><tr><td>Credential theft</td><td>Model is induced to read tokens</td><td>Broker, minimal injection, log redaction</td></tr><tr><td>Data exfiltration</td><td>Malicious documents induce uploads</td><td>egress allowlist, DLP, read-only mounts</td></tr><tr><td>Duplicate side effects</td><td>Retry after timeout causes duplicate sending</td><td>Idempotency keys, outbox, reconciliation</td></tr><tr><td>Malicious attachments</td><td>Macros, zip bombs, path traversal</td><td>Sandboxed parsing, macro disabling, resource limits</td></tr><tr><td>Supply chain</td><td>Dependencies/skills tampered with</td><td>Version pinning, signatures, SBOM, review</td></tr><tr><td>Sandbox escape</td><td>Malicious code breaks out of the container</td><td>Strong isolation, non-root, no host sockets</td></tr><tr><td>Memory poisoning</td><td>Untrusted sources write long-term preferences</td><td>quarantine, dual-source, user confirmation</td></tr><tr><td>Device loss</td><td>Phone or computer used by someone else</td><td>Revocation, expiration, biometrics, encryption</td></tr><tr><td>Over-automation</td><td>Agent expands scope without supervision</td><td>Mandate, budget, kill switch</td></tr></tbody></table><h3 id="capability-model" tabindex="-1">Capability model <a class="header-anchor" href="#capability-model" aria-label="Permalink to &quot;Capability model&quot;">​</a></h3><p>A Capability is not “an Agent has a tool,” but a permission for a specific resource, action, scope, and time limit:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Capability</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  action</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  resource</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  scope</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Record</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  constraints</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Record</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">unknown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  expiresAt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  revokedAt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  issuedBy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  mandateId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>Principles: least privilege, short-lived validity, reclamation when the Task ends, scoped by device/account/resource/action, Executor cannot self-sign or expand, all use is auditable, revocation takes effect immediately.</p><h3 id="risk-levels" tabindex="-1">Risk levels <a class="header-anchor" href="#risk-levels" aria-label="Permalink to &quot;Risk levels&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Level</th><th>Example</th><th>Default handling</th></tr></thead><tbody><tr><td>R0 Read-only</td><td>Viewing files, reading email, searching</td><td>May be automatic</td></tr><tr><td>R1 Low-risk writes</td><td>Drafts, temporary files, workspace changes</td><td>Automatic within Mandate</td></tr><tr><td>R2 Externally visible</td><td>Sending email, comments, sharing</td><td>Approval on first use or every use</td></tr><tr><td>R3 Irreversible</td><td>Deletion, payments, permission changes, public publishing</td><td>Strong approval + Receipt + compensation</td></tr><tr><td>R4 Prohibited</td><td>Bypassing security controls, leaking secrets, unauthorized transfers</td><td>Denied by the system</td></tr></tbody></table><h3 id="credentials-and-secrets" tabindex="-1">Credentials and secrets <a class="header-anchor" href="#credentials-and-secrets" aria-label="Permalink to &quot;Credentials and secrets&quot;">​</a></h3><ul><li>Long-term secrets exist only in the Broker/key vault;</li><li>Model context never contains refresh tokens, private keys, or cookies;</li><li>Short-term tokens are injected only when calling external APIs;</li><li>Logs, exceptions, screenshots, and Artifact content are scanned for sensitive information;</li><li>Development, testing, and production use different credentials;</li><li>Local storage and backups are encrypted;</li><li>Revocation by connection, device, and account is supported;</li><li>Users can view “who used what permission and when”.</li></ul><h3 id="sandbox-network-and-prompt-injection" tabindex="-1">Sandbox, network, and prompt injection <a class="header-anchor" href="#sandbox-network-and-prompt-injection" aria-label="Permalink to &quot;Sandbox, network, and prompt injection&quot;">​</a></h3><ul><li>Minimal mounts and shortest lifecycle by default;</li><li>Deny outbound by default; open allowlists per Task;</li><li>External pages and documents are marked as untrusted;</li><li>Untrusted content cannot directly determine tool calls;</li><li>High-risk actions must pass through the Effect Dispatcher and approval;</li><li>Downloads, macros, and attachments enter quarantine;</li><li>Sandbox failures are treated as security incidents and are not masked with “try again.”</li></ul><h3 id="privacy-and-local-first" tabindex="-1">Privacy and local-first <a class="header-anchor" href="#privacy-and-local-first" aria-label="Permalink to &quot;Privacy and local-first&quot;">​</a></h3><ul><li>Local storage by default;</li><li>Upload only the minimal context required by the Task;</li><li>Sensitive data can be designated for local models or manual handling;</li><li>Memory, logs, and Artifact have sensitivity levels;</li><li>Deletion and forgetting must propagate;</li><li>Backups are encrypted;</li><li>Data export and migration are available;</li><li>User data is not used for training or sharing without consent.</li></ul><h3 id="supply-chain-and-extensions" tabindex="-1">Supply chain and extensions <a class="header-anchor" href="#supply-chain-and-extensions" aria-label="Permalink to &quot;Supply chain and extensions&quot;">​</a></h3><ul><li>Dependencies are version-locked, verified, and covered by SBOM;</li><li>Skills/plugins are signed or source-verified;</li><li>Third-party Connectors use least privilege;</li><li>Plugins cannot bypass Policy;</li><li>High-risk extensions require manual review;</li><li>Run security and contract tests before upgrades.</li></ul><h3 id="multi-device-security" tabindex="-1">Multi-device security <a class="header-anchor" href="#multi-device-security" aria-label="Permalink to &quot;Multi-device security&quot;">​</a></h3><ul><li>Device pairing uses short-term codes and public keys;</li><li>Phones do not hold long-term master credentials;</li><li>Approvals are bound to nonce, parameters, and expiration time;</li><li>Lost devices can be revoked remotely;</li><li>Offline caches are read-only and produce no external side effects;</li><li>Only necessary projections and artifact references are synchronized across devices;</li><li>Memory deletion cannot be resurrected on another device.</li></ul><h3 id="incident-response-and-kill-switch" tabindex="-1">Incident response and kill switch <a class="header-anchor" href="#incident-response-and-kill-switch" aria-label="Permalink to &quot;Incident response and kill switch&quot;">​</a></h3><ul><li>Global stop switch;</li><li>Local stops by device, Connector, skill, Task, and account;</li><li>After stopping, audit and recovery entry points are retained;</li><li>Key rotation;</li><li>Clean up affected credentials and caches after an incident;</li><li>Output readable incident reports;</li><li>Do not treat “restarting the service” as incident handling.</li></ul><h3 id="backup-recovery-and-deletion" tabindex="-1">Backup, recovery, and deletion <a class="header-anchor" href="#backup-recovery-and-deletion" aria-label="Permalink to &quot;Backup, recovery, and deletion&quot;">​</a></h3><ul><li>Encrypted backups;</li><li>After recovery, verify events, artifacts, memory, and permissions;</li><li>Deletion propagates to projections, indexes, caches, and devices;</li><li>Retain the minimum information required for auditing, but do not retain sensitive content that should not be retained;</li><li>Users can export their own data;</li><li>Re-verify after migration; do not assume the copy succeeded.</li></ul><h3 id="security-testing" tabindex="-1">Security testing <a class="header-anchor" href="#security-testing" aria-label="Permalink to &quot;Security testing&quot;">​</a></h3><ul><li>Prompt injection and tool privilege escalation;</li><li>Secret leakage;</li><li>Path traversal, macros, zip bombs;</li><li>Sandbox escape;</li><li>Network egress bypass;</li><li>Approval replay;</li><li>Device revocation;</li><li>Duplicate side effects;</li><li>Supply chain tampering;</li><li>Memory poisoning;</li><li>Data and backup deletion.</li></ul>`,32)])])}const k=e(n,[["render",r]]);export{u as __pageData,k as default};
